const $=s=>document.querySelector(s);
const paths={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',box:'m3 7 9-5 9 5-9 5Zm0 0v10l9 5 9-5V7M12 12v10M7 4l10 6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',help:'M9 9a3 3 0 1 1 4 3c-1 1-1 2-1 3m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',truck:'M1 5h13v12H1Zm13 5h5l4 4v3h-9M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0m13 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Zm-4 10 3 3 5-6',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shoe:'m3 14 4-5 4 4 5 1 4 2v4H3Zm5-2 2-2m1 4 2-2',shirt:'m8 3 4 2 4-2 6 5-4 4-2-2v11H8V10l-2 2-4-4Z',coffee:'M5 4h11v13H5ZM16 7h3a3 3 0 0 1 0 6h-3M3 21h17',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',back:'M19 12H5m5-5-5 5 5 5',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 3a4 4 0 1 1 0 8M22 21v-3a4 4 0 0 0-3-4M12 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chart:'M4 3v18h17M8 16v-5m5 5V6m5 10v-7'};
const icon=(n)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.box}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`S/ ${Number(n).toFixed(2)}`;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateLabel=d=>new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const addDay=n=>{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const statuses=['Solicitud registrada','Recojo programado','Producto recogido','En camino al comercio','Entregado al comercio'];
const seed=()=>[
{id:'RV-1042',product:'Zapatillas urbanas',store:'Falabella',category:'Calzado',type:'shoe',value:189,auth:'DEV-84021',deadline:addDay(12),district:'Miraflores',address:'Av. La Paz 1240, dpto. 302',destination:'Punto de devolución indicado por la tienda · San Isidro',date:addDay(1),slot:'18:00 – 20:00',name:'Valeria Torres',phone:'999 123 456',fee:15,stage:1,courier:'Diego Ramírez',notes:'Tocar el timbre del departamento.',events:[{stage:0,text:'Solicitud registrada con autorización de devolución.'},{stage:1,text:'Diego Ramírez realizará el recojo en la franja elegida.'}]},
{id:'RV-1041',product:'Cafetera de goteo',store:'Mercado Libre',category:'Tecnología y hogar',type:'coffee',value:159,auth:'DEV-ML-3850',deadline:addDay(8),district:'Surco',address:'Av. Benavides 1820, dpto. 401',destination:'Agencia asignada por el comercio · Surco',date:today(),slot:'14:00 – 16:00',name:'Valeria Torres',phone:'999 123 456',fee:18,stage:3,courier:'Lucía Mendoza',notes:'Producto embalado y etiqueta colocada.',events:[{stage:0,text:'Solicitud registrada.'},{stage:1,text:'Recojo coordinado.'},{stage:2,text:'Paquete recogido. Constancia de custodia simulada.'},{stage:3,text:'En traslado al punto indicado por el comercio.'}]},
{id:'RV-1036',product:'Casaca de denim',store:'Ripley',category:'Ropa',type:'shirt',value:129,auth:'DEV-RP-1932',deadline:addDay(5),district:'San Isidro',address:'Calle Los Pinos 218',destination:'Punto indicado por el comercio · San Isidro',date:addDay(-2),slot:'10:00 – 12:00',name:'Valeria Torres',phone:'999 123 456',fee:15,stage:4,courier:'Diego Ramírez',notes:'',receiver:'Mesa de recepción · demostración',events:statuses.map((_,i)=>({stage:i,text:i===4?'Entrega registrada en el punto del comercio.':'Etapa completada en la demostración.'}))}
];
let storageAvailable=true;let orders;try{orders=JSON.parse(localStorage.getItem('reversa-orders-v1'))||seed();if(!Array.isArray(orders))orders=seed()}catch{orders=seed();storageAvailable=false}
let role='buyer',filter='all',search='',step=1,draft={},created=null;
const save=()=>{try{localStorage.setItem('reversa-orders-v1',JSON.stringify(orders))}catch{storageAvailable=false;toast('El navegador no permite guardar: los cambios durarán esta sesión.')}};
const toast=m=>{$('#toast').textContent=m;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)};
function badge(o){return `<span class="badge ${o.issue?'red':o.stage===4?'green':o.stage>=2?'purple':''}">${esc(o.issue?'Recojo por reprogramar':statuses[o.stage])}</span>`}
const navs=[['home','Inicio','home'],['orders','Mis devoluciones','box'],['new','Solicitar recojo','plus'],['how','Cómo funciona','help']];
function current(){return location.hash.slice(1)||'home'}
function shell(content){const page=current().split('/')[0];const ns=role==='admin'?[['admin','Operaciones','chart'],['orders','Devoluciones','box'],['how','Cómo funciona','help']]:navs;return `<div class="shell"><aside class="sidebar"><a href="#${role==='admin'?'admin':'home'}" aria-label="Reversa, inicio"><img class="brand" src="assets/logo.jpg" alt="Reversa"></a><p class="nav-label">${role==='admin'?'ADMINISTRACIÓN':'TU ESPACIO REVERSA'}</p><nav class="nav" aria-label="Navegación principal">${ns.map(([p,t,i])=>`<a href="#${p}" class="${page===p?'active':''}">${icon(i)}${t}${p==='orders'?`<span class="num">${orders.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card">${icon('shield')}<strong>Tu devolución, acompañada.</strong><p>Nos encargamos del trayecto. Tú sigues con tu día.</p><a href="#how">Conoce el proceso ${icon('arrow')}</a></div><p class="demo-label">PROTOTIPO INTERACTIVO · PC1</p><button class="reset" data-action="reset">Reiniciar demostración</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Tu espacio <span>/</span><strong>${({home:'Inicio',orders:'Devoluciones',new:'Solicitar recojo',track:'Seguimiento',admin:'Operaciones',how:'Cómo funciona'})[page]||'Inicio'}</strong></div><a href="#home"><img class="mobile-brand" src="assets/logo.jpg" alt="Reversa"></a><div class="top-actions"><div class="role-switch" aria-label="Vista de demostración"><button data-role="buyer" class="${role==='buyer'?'selected':''}">Comprador</button><button data-role="admin" class="${role==='admin'?'selected':''}">Administrador</button></div><div class="user"><div class="avatar">${role==='admin'?'AD':'VT'}</div><span>${role==='admin'?'Equipo Reversa':'Valeria Torres'}<small>${role==='admin'?'Operaciones · demo':'Cuenta de demostración'}</small></span></div></div></header><div class="content">${content}<footer class="footer"><span>© 2026 Reversa · Dale la vuelta a tus devoluciones.</span><span>Demostración · Sin cobros ni recojos reales.</span></footer></div></main><nav class="mobile-nav" aria-label="Navegación móvil">${ns.map(([p,t,i])=>`<a href="#${p}" class="${page===p?'active':''}">${icon(i)}${p==='new'?'Solicitar':p==='orders'?'Devoluciones':t}</a>`).join('')}</nav></div>`}
function heading(title,sub,action='',eyebrow='MENOS VUELTAS. MÁS TIEMPO PARA TI.'){return `<div class="heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function stats(){return `<div class="stats"><div class="stat"><div class="stat-icon">${icon('box')}</div><div><strong>${orders.filter(o=>o.stage<4).length}</strong><span>Devoluciones en curso</span></div></div><div class="stat"><div class="stat-icon">${icon('calendar')}</div><div><strong>${orders.filter(o=>o.stage<2).length}</strong><span>Recojos pendientes</span></div></div><div class="stat"><div class="stat-icon">${icon('check')}</div><div><strong>${orders.filter(o=>o.stage===4).length}</strong><span>Entregadas al comercio</span></div></div></div>`}
function orderCard(o){return `<article class="card order-card"><div class="order-head"><span class="order-id">${esc(o.id)}</span>${badge(o)}</div><div class="product"><div class="product-icon">${icon(o.type)}</div><div><h3>${esc(o.product)}</h3><p>${esc(o.store)} <span>·</span> ${esc(o.category)}</p></div></div><div class="order-meta"><span>${icon('calendar')}${dateLabel(o.date)} · ${esc(o.slot)}</span><span>${icon('pin')}${esc(o.district)}</span></div><div class="mini-progress" aria-label="Etapa ${o.stage+1} de 5">${statuses.map((_,i)=>`<span class="${i<=o.stage?'done':''}"></span>`).join('')}</div><div class="order-bottom"><span>${o.stage===4?'Trayecto completado':o.issue?'Elige una nueva franja horaria':o.stage>=2?'Tu paquete sigue avanzando':'Nos vemos en el horario elegido'}</span><a class="btn ghost" href="#track/${esc(o.id)}">Ver seguimiento ${icon('arrow')}</a></div></article>`}
function parcelArt(){return `<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 320 250"><ellipse cx="167" cy="219" rx="99" ry="15" fill="#411654" opacity=".3"/><path d="M64 91 161 45 258 91 161 140Z" fill="#ffc487"/><path d="M64 91v105l97 47V140Z" fill="#eaa15b"/><path d="M161 140 258 91v105l-97 47Z" fill="#f9b773"/><path d="m102 73 98 48 0 37 24-12V110l-98-48Z" fill="#ffe3bb"/><path d="m178 179 38-19v24l-38 19Z" fill="#fff4e4"/><path d="m183 180 26-13m-26 20 18-9" stroke="#bb8d64" stroke-width="3"/><path d="M44 174c-25-42 18-101 64-119" stroke="#ff932c" stroke-width="13" fill="none"/><path d="m89 38 29 12-13 28" stroke="#ff932c" stroke-width="13" fill="none"/><circle cx="261" cy="54" r="29" fill="#fff"/><path d="m248 54 9 9 17-19" stroke="#6e3189" stroke-width="5" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="floating one">${icon('check')}Recojo a tu ritmo</div><div class="floating two">${icon('shield')}Siempre sabes dónde está</div></div>`}
function home(){return heading('Hola, Valeria 👋','Tu día ya tiene suficientes vueltas. De tu devolución nos encargamos nosotros.',`<span class="date-pill">${icon('calendar')} ${new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'long',timeZone:'America/Lima'}).format(new Date())}</span>`)+`<section class="hero"><div class="hero-copy"><p class="eyebrow">TÚ ELIGES EL HORARIO. NOSOTROS EL TRAYECTO.</p><h2>Devuelve tu compra.<br><em>Recupera tu tiempo.</em></h2><p>Recogemos tu producto y lo llevamos al punto indicado por la tienda. Sin reorganizar todo tu día.</p><a href="#new" class="btn orange">${icon('plus')} Solicitar un recojo ${icon('arrow')}</a></div>${parcelArt()}</section>`+stats()+`<div class="dashboard-grid"><section><div class="section-title"><div><h2>Tus devoluciones en curso</h2><p>Cada paso, claro y a la mano.</p></div><a href="#orders" class="btn ghost">Ver todas ${icon('arrow')}</a></div>${orders.filter(o=>o.stage<4).slice(0,2).map(orderCard).join('')||empty('Todo al día','Aquí aparecerán tus próximos recojos.')}</section><aside class="dashboard-aside"><div class="card how"><h3>Una devolución, menos vueltas.</h3>${[['Primero, autoriza con la tienda','Solicita tu devolución y conserva el código y las instrucciones.'],['Elige cuándo te recogemos','Registra tu paquete, dirección y una franja que encaje contigo.'],['Nosotros lo llevamos','Sigue el trayecto y recibe una constancia de entrega.']].map(([h,p],i)=>`<div class="how-step"><span class="step-number">0${i+1}</span><div><h4>${h}</h4><p>${p}</p></div></div>`).join('')}<div class="note">${icon('info')}La aprobación y el reembolso dependen de la tienda. Reversa se encarga del recojo y la entrega.</div></div><div class="coverage">${icon('pin')}<div><h4>Empezamos cerca de ti</h4><p>Cobertura piloto simulada en 5 distritos de Lima.</p></div></div></aside></div>`}
function empty(h,p){return `<div class="empty">${icon('box')}<h3>${h}</h3><p>${p}</p>${role==='buyer'?'<a class="btn" href="#new">Solicitar un recojo</a>':''}</div>`}
function filtered(){return orders.filter(o=>(filter==='all'||filter==='active'&&o.stage<4||filter==='done'&&o.stage===4||filter==='issue'&&o.issue)&&[o.id,o.product,o.store,o.name].join(' ').toLowerCase().includes(search.toLowerCase()))}
function filters(){return `<div class="filters">${[['all','Todas'],['active','En curso'],['done','Entregadas'],['issue','Incidencias']].map(([v,t])=>`<button class="filter ${filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div>`}
function ordersPage(){return heading(role==='admin'?'Todas las devoluciones':'Mis devoluciones','Consulta tus solicitudes y sigue cada etapa del trayecto.',role==='buyer'?'<a class="btn" href="#new">'+icon('plus')+' Nuevo recojo</a>':'')+`<div class="toolbar"><input class="search" aria-label="Buscar devoluciones" placeholder="Buscar por código, producto o tienda…" value="${esc(search)}" id="search-orders"></div>${filters()}<div id="order-results" class="list-grid">${filtered().map(orderCard).join('')||empty('Sin devoluciones en esta vista','Prueba con otra búsqueda o cambia el filtro.')}</div>`}
function field(label,name,type='text',extra='',full=false){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(draft[name]||'')}" ${extra}></label>`}
const districts=['Miraflores','San Isidro','Surco','San Borja','Barranco'];
const fee=()=>draft.size==='medium'?18:15;
function summary(){return `<aside class="card summary"><h3>Tu recojo, en resumen</h3><div class="summary-line"><span>Producto</span><strong>${esc(draft.product||'Por completar')}</strong></div><div class="summary-line"><span>Comercio</span><strong>${esc(draft.store||'Por completar')}</strong></div><div class="summary-line"><span>Recojo en</span><strong>${esc(draft.district||'Por elegir')}</strong></div><div class="summary-line"><span>Fecha</span><strong>${draft.date?dateLabel(draft.date):'Por elegir'}</strong></div><div class="summary-line"><span>Franja horaria</span><strong>${esc(draft.slot||'Por elegir')}</strong></div><div class="summary-line total"><span>Servicio simulado</span><strong>${money(fee())}</strong></div><div class="note">${icon('info')}Tarifa de ejemplo para validar el prototipo. No se realiza ningún cobro.</div><div class="route-note">${icon('shield')} Recojo → traslado → entrega al punto indicado por el comercio.<br>La tarifa no incluye el reembolso del producto.</div></aside>`}
function newPage(){if(created)return heading('Todo listo para dar la vuelta.','Tu solicitud de demostración quedó registrada.')+`<div class="card success"><div class="success-icon">${icon('check')}</div><h2>¡Recojo solicitado!</h2><p>Tu código es <strong>${esc(created.id)}</strong>.<br>Pasaremos por ${esc(created.district)} el ${dateLabel(created.date)}, de ${esc(created.slot)}. Puedes seguir el avance en cualquier momento.</p><a class="btn" href="#track/${created.id}">Ver mi seguimiento ${icon('arrow')}</a><a class="btn outline" href="#home">Volver al inicio</a><p>Simulación sin cobros. El administrador puede coordinar el recojo y avanzar sus etapas.</p></div>`;
let body='';if(step===1)body=`<h2>Cuéntanos qué vas a devolver</h2><p class="subtitle">La tienda ya debe haber autorizado tu devolución.</p><div class="note">${icon('info')}Reversa es un servicio externo de recojo y entrega. No autoriza devoluciones ni representa a las tiendas.</div><div class="fields">${field('Producto','product','text','required maxlength="90" placeholder="Ej. Zapatillas urbanas"',true)}<label class="field">Tienda o plataforma<select name="store" required><option value="">Selecciona el comercio</option>${['Falabella','Mercado Libre','Ripley','Oechsle','Otro comercio'].map(v=>`<option ${draft.store===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Categoría<select name="category" required>${['Calzado','Ropa','Tecnología y hogar','Accesorios'].map(v=>`<option ${draft.category===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('Valor del producto (S/)','value','number','required min="1" max="20000" step="0.01" placeholder="Ej. 189"')}<label class="field">Tamaño del paquete<select name="size"><option value="small" ${draft.size==='small'?'selected':''}>Pequeño · hasta 3 kg · S/ 15</option><option value="medium" ${draft.size==='medium'?'selected':''}>Mediano · hasta 5 kg · S/ 18</option></select><small>Piloto: hasta 50 × 40 × 40 cm. No incluye muebles, electrodomésticos grandes ni productos peligrosos.</small></label>${field('Código de autorización de devolución','auth','text','required maxlength="70" placeholder="Código proporcionado por la tienda"',true)}${field('Último día para entregar al comercio','deadline','date',`required min="${addDay(2)}"`,true)}${field('Punto o dirección de entrega indicado por la tienda','destination','text','required minlength="10" maxlength="200" placeholder="Nombre del punto, dirección y distrito"',true)}</div><label class="check"><input type="checkbox" name="authorized" required ${draft.authorized?'checked':''}><span>Confirmo que la devolución ya fue autorizada y que el punto de entrega acepta este paquete. Seguiré los requisitos y el embalaje indicados por el comercio.</span></label>`;
if(step===2)body=`<h2>Un recojo que encaje contigo</h2><p class="subtitle">Elige dónde y cuándo. Las franjas son simuladas.</p><div class="fields">${field('Persona de contacto','name','text','required maxlength="80"',true)}${field('Celular','phone','tel','required pattern="[0-9 +()-]{9,18}" maxlength="18" placeholder="999 123 456"')}<label class="field">Distrito de recojo<select name="district" required><option value="">Selecciona tu distrito</option>${districts.map(v=>`<option ${draft.district===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('Dirección de recojo y departamento','address','text','required minlength="8" maxlength="180" placeholder="Av. / calle, número, departamento"',true)}${field('Fecha de recojo','date','date',`required min="${addDay(1)}" max="${draft.deadline?new Date(new Date(draft.deadline+'T12:00:00Z').getTime()-86400000).toISOString().slice(0,10):addDay(30)}"`,true)}</div><p class="subtitle">Reserva al menos un día entre el recojo y la fecha límite de entrega.</p><div class="field full" style="margin-top:20px">Franja horaria<div class="slots">${['10:00 – 12:00','14:00 – 16:00','18:00 – 20:00'].map(v=>`<button type="button" class="slot ${draft.slot===v?'active':''}" data-slot="${v}" aria-pressed="${draft.slot===v}">${v}</button>`).join('')}</div></div><label class="field full" style="margin-top:20px">Indicaciones para el recojo (opcional)<textarea name="notes" maxlength="300" placeholder="Ej. Tocar el timbre del departamento.">${esc(draft.notes||'')}</textarea></label>`;
if(step===3)body=`<h2>Una última mirada y listo</h2><p class="subtitle">Revisa los datos antes de confirmar la solicitud.</p><div class="detail-row"><span>Producto y autorización</span>${esc(draft.product)} · ${esc(draft.store)}<br>${esc(draft.auth)} · valor: ${money(draft.value)}</div><div class="detail-row"><span>Recogemos en</span>${esc(draft.address)}, ${esc(draft.district)}<br>${esc(draft.name)} · ${esc(draft.phone)}</div><div class="detail-row"><span>Llevamos a</span>${esc(draft.destination)}<br>Fecha límite indicada: ${dateLabel(draft.deadline)}</div><div class="detail-row"><span>Tu cita simulada</span>${dateLabel(draft.date)} · ${esc(draft.slot)}</div><div class="note" style="margin-top:20px">${icon('box')}Prepara el paquete con la protección, accesorios y etiqueta que pide tu tienda. En este piloto, Reversa transporta el producto ya embalado.</div><label class="check"><input type="checkbox" name="accept" required><span>Confirmo los datos y entiendo que esta es una simulación. La entrega no garantiza la aceptación ni el reembolso; esas decisiones corresponden al comercio.</span></label>`;
return heading('Solicitar un recojo','Tu devolución autorizada, del punto A al punto listo.')+`<div class="form-layout"><section class="card form-card"><div class="wizard">${['Tu devolución','Recojo','Confirmación'].map((v,i)=>`<div class="${step>=i+1?'current':''}">0${i+1} · ${v}</div>`).join('')}</div><form id="request-form">${body}<div class="form-actions"><button type="button" class="btn outline" data-action="prev">${icon('back')} ${step===1?'Volver':'Anterior'}</button><button type="submit" class="btn">${step===3?'Confirmar recojo simulado':'Continuar'} ${icon('arrow')}</button></div></form></section>${summary()}</div>`}
function timeline(o){return `<div class="timeline">${statuses.map((s,i)=>{const event=(o.events||[]).filter(e=>e.stage===i).at(-1);return `<div class="event ${i<=o.stage?'complete':''}"><h4>${s}</h4><p>${esc(event?.text||['Recibiremos los datos de tu solicitud.','Coordinaremos la franja y el responsable.','Registraremos la recepción del paquete.','Trasladaremos al punto indicado.','Registraremos la constancia de entrega.'][i])}</p>${event?.time?`<small>${esc(event.time)}</small>`:''}</div>`}).join('')}</div>`}
function tracking(id){const o=orders.find(o=>o.id===id);if(!o)return empty('No encontramos ese código','Revisa el código en tus devoluciones.');return heading('Cada paso de tu devolución.',`${esc(o.id)} · ${esc(o.store)}`,`<a class="btn outline" href="#${role==='admin'?'admin':'orders'}">${icon('back')} Volver</a>`,'TU PAQUETE, SIEMPRE A LA VISTA.')+`<div class="tracking-layout"><section class="card detail-card"><div class="section-title"><h2>Seguimiento del trayecto</h2>${badge(o)}</div><div class="product"><div class="product-icon">${icon(o.type)}</div><div><h3>${esc(o.product)}</h3><p>Autorización: ${esc(o.auth)}</p></div></div>${o.issue?`<div class="note">${icon('info')}${esc(o.issue)}. Reprograma el recojo para continuar. No se marca el paquete como recogido.</div>`:''}${timeline(o)}${o.stage===4?`<div class="receipt"><h4>${icon('check')} Constancia de entrega simulada</h4><p>${esc(o.id)} · ${esc(o.destination)}<br>Recepción: ${esc(o.receiver||'Recepción del comercio · demo')}<br>Paquete entregado por ${esc(o.courier)}.</p><button class="btn outline" data-download="${o.id}">${icon('download')} Descargar constancia</button></div>`:''}<div class="route-note">${icon('info')}El seguimiento termina con la entrega al comercio. Consulta directamente con la tienda el estado de aceptación y reembolso.</div></section><aside><div class="card detail-card"><h3>Detalles del recojo</h3><div class="detail-row"><span>Fecha y franja</span>${dateLabel(o.date)} · ${esc(o.slot)}</div><div class="detail-row"><span>Dirección</span>${esc(o.address)}, ${esc(o.district)}</div><div class="detail-row"><span>Persona de contacto</span>${esc(o.name)} · ${esc(o.phone)}</div><div class="detail-row"><span>Responsable de recojo</span>${esc(o.courier||'Pendiente de asignación')}</div><div class="detail-row"><span>Destino indicado por el comercio</span>${esc(o.destination)}</div><div class="detail-row"><span>Tarifa de demostración</span>${money(o.fee)} · sin cobro</div>${o.notes?`<div class="detail-row"><span>Indicaciones</span>${esc(o.notes)}</div>`:''}${o.stage<2?`<button style="margin-top:20px;width:100%" class="btn outline" data-reschedule="${o.id}">${icon('calendar')} Reprogramar recojo</button>`:''}</div>${role==='admin'?`<div class="card detail-card" style="margin-top:18px"><h3>Acciones de operación</h3><p class="subtitle">Actualiza el recorrido de demostración.</p>${o.stage<4?`<button class="btn" style="margin-top:15px;width:100%" data-advance="${o.id}">${o.stage===0?'Asignar y programar':o.stage===1?'Confirmar recojo':o.stage===2?'Iniciar traslado':'Registrar entrega'} ${icon('arrow')}</button>`:''}${o.stage<2&&!o.issue?`<button class="btn outline" style="margin-top:10px;width:100%" data-issue="${o.id}">Registrar incidencia</button>`:''}</div>`:''}</aside></div>`}
function table(){return `<div class="card table-wrap"><table class="admin-table"><thead><tr><th>Solicitud / comprador</th><th>Producto / comercio</th><th>Recojo</th><th>Responsable</th><th>Estado</th><th></th></tr></thead><tbody>${filtered().map(o=>`<tr><td><strong>${o.id}</strong><small>${esc(o.name)}</small></td><td>${esc(o.product)}<small>${esc(o.store)}</small></td><td>${dateLabel(o.date)}<small>${esc(o.slot)} · ${esc(o.district)}</small></td><td>${esc(o.courier||'Sin asignar')}</td><td>${badge(o)}</td><td><a class="btn ghost" href="#track/${o.id}">Gestionar ${icon('arrow')}</a></td></tr>`).join('')||'<tr><td colspan="6">No hay solicitudes que coincidan.</td></tr>'}</tbody></table></div>`}
function admin(){return heading('Cada devolución, bajo control.','Coordina recojos, registra incidencias y confirma las entregas.','<button class="btn outline" data-action="export">'+icon('download')+' Exportar CSV</button>','CENTRO DE OPERACIONES · REVERSA')+`<div class="admin-banner">${icon('info')} Vista de administración de demostración. Comparte los pedidos de este navegador con la vista comprador. No se contacta a transportistas ni comercios.</div>`+stats()+`<div class="section-title"><div><h2>Solicitudes de devolución</h2><p>Gestiona el trayecto completo desde una sola vista.</p></div></div><div class="toolbar"><input id="search-orders" class="search" aria-label="Buscar solicitudes" placeholder="Buscar código, comprador o producto…" value="${esc(search)}"></div>${filters()}<div id="order-results">${table()}</div>`}
function howPage(){return heading('Devolver no debería detener tu día.','Un servicio externo para el trayecto de tu devolución, con cada paso claro.')+`<div class="info-grid">${[['shield','01 · Autoriza con tu tienda','Solicita la devolución directamente al comercio. Conserva la autorización, la fecha límite y el punto de entrega.'],['calendar','02 · Agenda el recojo','Registra tu paquete ya embalado, elige una franja horaria y revisa la tarifa antes de confirmar.'],['truck','03 · Sigue hasta la entrega','El administrador coordina el recojo y actualiza el trayecto. Al llegar al comercio, obtienes una constancia de entrega.']].map(([i,h,p])=>`<div class="card info-card">${icon(i)}<h3>${h}</h3><p>${p}</p></div>`).join('')}</div><section class="card faq"><h2 style="font-size:19px">Todo claro, antes de empezar.</h2>${[['¿Qué hace Reversa?','Recoge productos cuya devolución ya está autorizada y los entrega al punto indicado por el comercio. Es un servicio independiente: no solicita la autorización, no decide si el producto es aceptado y no procesa reembolsos.'],['¿Qué cobertura y paquetes incluye este prototipo?','Simulamos recojos en Miraflores, San Isidro, Surco, San Borja y Barranco. El piloto considera paquetes pequeños o medianos, hasta 5 kg y 50 × 40 × 40 cm, ya embalados. Son supuestos de diseño por validar, no cobertura operativa real.'],['¿Cuánto cuesta?','La demostración utiliza S/ 15 para paquetes pequeños y S/ 18 para medianos. Son precios hipotéticos para explorar la disposición a pagar; la PC1 no valida una tarifa ni la rentabilidad. No se realiza ningún pago.'],['¿Qué pasa si el recojo no se concreta?','El administrador registra la incidencia sin marcar el paquete como recogido. El comprador puede seleccionar otra fecha y franja, respetando la fecha límite indicada por el comercio.'],['¿La entrega asegura que me reembolsen?','No. La constancia registra la entrega logística simulada. La revisión del producto, la aceptación de la devolución y el reembolso corresponden al comercio.'],['¿Cómo presentar la demostración?','Cambia entre Comprador y Administrador en la barra superior. Solicita un recojo, entra a Operaciones, asígnalo y avanza sus etapas. Vuelve al comprador para consultar el seguimiento y descargar la constancia. Los datos se guardan solo en este navegador; usa Reiniciar demostración para recuperar los ejemplos.'],['¿Cómo se relaciona con la PC1?','El prototipo explora la reducción del traslado, la incompatibilidad de horarios y la incertidumbre del recojo. La investigación valida la existencia del problema en parte de la muestra; este diseño no representa una solución ni una demanda comercial ya validadas.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<button class="btn outline" style="margin-top:20px" data-action="reset">Reiniciar demostración</button></section>`}
function render(){const p=current().split('/');if(p[0]==='admin'&&role!=='admin'){role='admin'}let content=({home,orders:ordersPage,new:newPage,admin,how:howPage})[p[0]];$('#app').innerHTML=shell(p[0]==='track'?tracking(decodeURIComponent(p[1]||'')):content?content():home());if(!storageAvailable)toast('Modo de sesión: los datos no se guardarán al cerrar.');}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}
function timeNow(){return new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Lima'}).format(new Date())}
function reschedule(id){const o=orders.find(x=>x.id===id);modal(`<h2>Reprogramar recojo</h2><p>Elige una nueva cita para ${esc(o.id)}. Deja al menos un día antes de la fecha límite del comercio.</p><form id="reschedule-form" data-id="${o.id}"><label class="field">Nueva fecha<input type="date" name="date" required min="${addDay(1)}" max="${new Date(new Date(o.deadline+'T12:00:00Z').getTime()-86400000).toISOString().slice(0,10)}" value="${o.date>=addDay(1)?o.date:addDay(1)}"></label><label class="field">Franja horaria<select name="slot">${['10:00 – 12:00','14:00 – 16:00','18:00 – 20:00'].map(v=>`<option ${v===o.slot?'selected':''}>${v}</option>`).join('')}</select></label><div class="modal-actions"><button type="button" class="btn outline" data-action="close">Cancelar</button><button class="btn" type="submit">Guardar nueva cita</button></div></form>`)}
function advance(id){if(role!=='admin')return;const o=orders.find(x=>x.id===id);if(o.stage>=4)return;if(o.issue){toast('Primero reprograma el recojo para resolver la incidencia.');return}const next=o.stage+1;modal(`<h2>${['','Asignar recojo','Confirmar recepción del paquete','Iniciar traslado','Registrar entrega al comercio'][next]}</h2><p>${esc(o.id)} · ${esc(o.product)}<br>${next===4?'Registra quién recibió el paquete en el punto indicado. Esta acción termina el servicio logístico simulado.':next===2?'Confirma la recepción del paquete embalado y su autorización antes de iniciar el traslado.':'Actualiza el avance de esta devolución de demostración.'}</p><form id="advance-form" data-id="${id}">${next===1?`<label class="field">Responsable<select name="courier" required><option>Diego Ramírez</option><option>Lucía Mendoza</option><option>Andrea Salazar</option></select></label>`:''}${next===4?'<label class="field">Recibido por<input name="receiver" required minlength="3" maxlength="100" placeholder="Ej. Mesa de recepción · demostración"></label>':''}<label class="field">Observación de la etapa<textarea name="observation" maxlength="250" placeholder="Agrega una observación (opcional)"></textarea></label><div class="modal-actions"><button type="button" class="btn outline" data-action="close">Cancelar</button><button class="btn" type="submit">Confirmar etapa</button></div></form>`)}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.role){role=b.dataset.role;filter='all';search='';location.hash=role==='admin'?'admin':'home';render()}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.slot){const f=$('#request-form');Object.assign(draft,Object.fromEntries(new FormData(f)));draft.slot=b.dataset.slot;render()}if(b.dataset.reschedule)reschedule(b.dataset.reschedule);if(b.dataset.advance)advance(b.dataset.advance);if(b.dataset.issue&&role==='admin'){modal(`<h2>Registrar incidencia</h2><p>El paquete seguirá pendiente de recojo hasta reprogramar.</p><form id="issue-form" data-id="${b.dataset.issue}"><label class="field">Motivo<select name="reason"><option>Comprador no disponible</option><option>Transportista no pudo acudir</option><option>Paquete no preparado</option><option>Dirección no localizada</option></select></label><div class="modal-actions"><button type="button" class="btn outline" data-action="close">Cancelar</button><button class="btn">Registrar incidencia</button></div></form>`)}if(b.dataset.download){const o=orders.find(x=>x.id===b.dataset.download);download(`Constancia-${o.id}.txt`,`REVERSA · CONSTANCIA DE ENTREGA SIMULADA\n\nSolicitud: ${o.id}\nProducto: ${o.product}\nComercio: ${o.store}\nAutorización: ${o.auth}\nDestino: ${o.destination}\nEntregado por: ${o.courier}\nRecibido por: ${o.receiver||'Recepción del comercio · demo'}\nRegistro: ${o.events.filter(e=>e.stage===4).at(-1)?.time||dateLabel(o.date)}\n\nEste documento es parte de un prototipo académico. No acredita una entrega real ni la aprobación o reembolso por parte del comercio.`)}if(b.dataset.action==='close')$('#modal').close();if(b.dataset.action==='prev'){const f=$('#request-form');Object.assign(draft,Object.fromEntries(new FormData(f)));if(step===1)location.hash='home';else{step--;render()}}if(b.dataset.action==='reset')modal(`<h2>Reiniciar la demostración</h2><p>Se eliminarán las solicitudes creadas en este navegador y se restaurarán los tres ejemplos iniciales.</p><div class="modal-actions"><button class="btn outline" data-action="close">Conservar datos</button><button class="btn" data-action="confirm-reset">Reiniciar</button></div>`);if(b.dataset.action==='confirm-reset'){orders=seed();save();draft={};created=null;step=1;filter='all';search='';$('#modal').close();location.hash=role==='admin'?'admin':'home';render();toast('Demostración restaurada.')}if(b.dataset.action==='export'){const rows=[['Código','Comprador','Producto','Comercio','Distrito','Fecha','Franja','Estado','Responsable','Tarifa simulada'],...filtered().map(o=>[o.id,o.name,o.product,o.store,o.district,o.date,o.slot,o.issue||statuses[o.stage],o.courier||'',o.fee])];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');download('reversa-operaciones.csv',csv,'text/csv;charset=utf-8');toast('Exportación descargada.')}});
document.addEventListener('input',e=>{if(e.target.id==='search-orders'){search=e.target.value;$('#order-results').innerHTML=role==='admin'&&current()==='admin'?table():filtered().map(orderCard).join('')||empty('Sin resultados','Prueba otra búsqueda.')}});
document.addEventListener('change',e=>{if(e.target.closest('#request-form')&&e.target.name==='size'){Object.assign(draft,Object.fromEntries(new FormData($('#request-form'))));render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));if(f.id==='request-form'){Object.assign(draft,data);if(step===2&&!draft.slot){toast('Selecciona una franja horaria.');return}if(step<3){step++;render();window.scrollTo({top:0,behavior:'smooth'});return}const id='RV-'+Math.max(1042,...orders.map(o=>Number(o.id.split('-')[1])))+'';const newId='RV-'+(Math.max(1042,...orders.map(o=>Number(o.id.split('-')[1])))+1);created={...draft,id:newId,value:Number(draft.value),fee:fee(),stage:0,type:draft.category==='Calzado'?'shoe':draft.category==='Ropa'?'shirt':draft.category==='Tecnología y hogar'?'coffee':'box',courier:'',events:[{stage:0,text:'Solicitud registrada. Pendiente de asignación del responsable.',time:timeNow()}]};orders.unshift(created);save();draft={};step=1;render();window.scrollTo({top:0,behavior:'smooth'});toast('Solicitud simulada registrada.')}if(f.id==='reschedule-form'){const o=orders.find(x=>x.id===f.dataset.id);Object.assign(o,data);o.issue=null;o.events.push({stage:o.stage,text:'Cita reprogramada para '+dateLabel(o.date)+' · '+o.slot+'.',time:timeNow()});save();$('#modal').close();render();toast('Nueva cita guardada.')}if(f.id==='advance-form'&&role==='admin'){const o=orders.find(x=>x.id===f.dataset.id);o.stage++;if(data.courier)o.courier=data.courier;if(data.receiver)o.receiver=data.receiver;o.events.push({stage:o.stage,text:data.observation||[null,'Recojo asignado a '+o.courier+'.','Paquete embalado recibido por '+o.courier+'. Custodia simulada.','Paquete en traslado al punto indicado por el comercio.','Entrega registrada. Recibido por '+o.receiver+'.'][o.stage],time:timeNow()});save();$('#modal').close();render();toast('Etapa actualizada.')}if(f.id==='issue-form'&&role==='admin'){const o=orders.find(x=>x.id===f.dataset.id);o.issue=data.reason;o.events.push({stage:o.stage,text:'Incidencia de recojo: '+data.reason+'. Se requiere una nueva cita.',time:timeNow()});save();$('#modal').close();render();toast('Incidencia registrada.')}});
window.addEventListener('hashchange',()=>{if(current()==='new'&&!created&&Object.keys(draft).length===0){step=1;draft={category:'Calzado',size:'small',name:'Valeria Torres',phone:'999 123 456'}}else if(current()!=='new')created=null;render();window.scrollTo(0,0)});
window.addEventListener('storage',e=>{if(e.key==='reversa-orders-v1'){try{const parsed=JSON.parse(e.newValue);if(Array.isArray(parsed)){orders=parsed;render()}}catch{}}});
render();
